// The interface language (AppLanguage / AppLocalization in AppLanguage.swift). Every string is
// written in Simplified Chinese and English; Traditional Chinese, Japanese, Korean, Spanish,
// French, German and Portuguese come from the macOS translation table (translations.json,
// regenerated by tests/extract_translations.ps1), keyed by the English text. A string missing
// from that table is shown in English, exactly as on macOS.
#pragma once

#include <QLocale>
#include <QString>
#include <QStringList>
#include <QVariantMap>

namespace asb::i18n {

// Resolved codes: zh-Hans, zh-Hant, en, ja, ko, es, fr, de, pt.
// AppLanguage.systemPreferredLanguage: the first supported entry of `uiLanguages`, else English.
QString systemLanguage(const QStringList &uiLanguages);
// The "language" preference ("system" or a code); unknown values become English.
QString resolve(const QString &preference, const QStringList &uiLanguages = QLocale::system().uiLanguages());

// The language AppController shows; also used by the C++ text helpers.
void setLanguage(const QString &code);
QString language();

// AppLocalization.text.
QString text(const QString &zhHans, const QString &english);
// English text in the current language (the table, else English).
QString translate(const QString &english);
// One language's table, for QML ({} for zh-Hans and English).
QVariantMap table(const QString &code);
// Loads the table from a file instead of the :/translations.json resource (tests).
void loadTable(const QString &path);

// 万 / 亿 counts (AppLanguage.compactTokenCountText) for both Chinese scripts.
bool usesChineseNumbers();
QLocale locale();

} // namespace asb::i18n
